package org.sleepwell.app;
import android.content.*;import org.json.*;import org.junit.Test;import static org.junit.Assert.*;

/** Inert private SQLite/JSON/permission-reference fixtures; no OS grant or player calls. */
public final class AlarmSoundModeStorageTest {
 @Test public void legacySilentAndPlaylistPortableTemplatesRoundTripInactive()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture();Store store=f.open()){Alarm original=f.load();String raw=original.json().toString();assertFalse(original.json().has("soundMode"));assertEquals(raw,Alarm.read(original.json()).json().toString());for(AlarmSoundMode mode:new AlarmSoundMode[]{AlarmSoundMode.SILENT,new AlarmSoundMode(AlarmSoundMode.Kind.PLAYLIST,java.util.List.of("daybreak","content://inert.audio/private","chime"),true,java.util.Map.of("content://inert.audio/private","Private dawn"))}){original.soundMode=mode;store.save(original);JSONObject portable=store.backup();Backup.validate(portable);Backup.restoreData(store,portable);Alarm restored=store.alarm(1);assertEquals(mode,restored.soundMode);assertFalse(restored.enabled);assertEquals(original.tone,restored.tone);assertEquals(original.days,restored.days);assertEquals(mode,AlarmDefaultsJson.decode(AlarmDefaultsJson.encode(new AlarmDefaults(original))).create(9).soundMode);}}}
 @Test public void malformedPoliciesPreserveEvidenceAndRejectBeforeDataReplacement()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture();Store store=f.open()){JSONObject valid=AlarmSoundModeJson.encode(new AlarmSoundMode(AlarmSoundMode.Kind.PLAYLIST,java.util.List.of("daybreak","pulse"),false));for(Object bad:new Object[]{JSONObject.NULL,"Silent",new JSONObject(),new JSONObject(valid.toString()).put("shuffle",1),new JSONObject(valid.toString()).put("mode","UNKNOWN"),new JSONObject(valid.toString()).put("tracks",new JSONArray().put("daybreak").put("https://example.com/music")),new JSONObject(valid.toString()).put("tracks",new JSONArray().put("daybreak").put("daybreak")),new JSONObject(valid.toString()).put("extra",true)}){JSONObject raw=f.load().json().put("soundMode",bad);Alarm invalid=Alarm.read(raw);assertTrue(invalid.soundModeInvalid);assertEquals(AlarmSoundMode.SINGLE,invalid.soundMode);assertTrue(invalid.json().has("soundMode"));assertThrows(IllegalArgumentException.class,()->new AlarmDefaults(invalid));JSONObject portable=store.backup();portable.getJSONArray("alarms").put(0,raw);String before=BackupFingerprint.read(store);assertThrows(JSONException.class,()->Backup.restoreData(store,portable));assertEquals(before,BackupFingerprint.read(store));}}}
 @Test public void savedPlaylistAndTemplateRetainSharedImportedGrantWithFakeRelease()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture()){String uri="content://inert.audio/shared";SharedPreferences sounds=f.c.getSharedPreferences(f.database+"-mode-sounds",0),defaults=f.c.getSharedPreferences(f.database+"-mode-defaults",0);AlarmDefaultsSettings.Factory previous=AlarmDefaultsSettings.factory;AlarmDefaultsSettings.factory=c->AlarmDefaultsSettings.of(defaults);int[] releases={0};try{Alarm alarm=f.load();alarm.soundMode=new AlarmSoundMode(AlarmSoundMode.Kind.PLAYLIST,java.util.List.of("daybreak",uri),false);try(Store store=f.open()){store.save(alarm);}new AlarmToneImport.Result(uri,"Fixture",true,(c,u)->releases[0]++).discard(f.c,c->f.open(),sounds);assertEquals(0,releases[0]);AlarmDefaultsSettings.of(defaults).save(new AlarmDefaults(alarm));alarm.soundMode=AlarmSoundMode.SINGLE;try(Store store=f.open()){store.save(alarm);}new AlarmToneImport.Result(uri,"Fixture",true,(c,u)->releases[0]++).discard(f.c,c->f.open(),sounds);assertEquals(0,releases[0]);AlarmDefaultsSettings.of(defaults).save(null);new AlarmToneImport.Result(uri,"Fixture",true,(c,u)->releases[0]++).discard(f.c,c->f.open(),sounds);assertEquals(1,releases[0]);}finally{AlarmDefaultsSettings.factory=previous;f.c.deleteSharedPreferences(f.database+"-mode-sounds");f.c.deleteSharedPreferences(f.database+"-mode-defaults");}}}
 @Test public void privateJournalPinsOccurrencePolicyAndRejectsStaleDecoderBeforeCommit()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture()){String name=f.database+"-sequence";SharedPreferences preferences=f.c.getSharedPreferences(name,0);try{assertEquals(0,AlarmPlaylistJournal.read(preferences,"run","list"));assertTrue(AlarmPlaylistJournal.save(preferences,"run","list",2,()->true));assertEquals(2,AlarmPlaylistJournal.read(preferences,"run","list"));assertEquals(0,AlarmPlaylistJournal.read(preferences,"replacement","list"));assertEquals(0,AlarmPlaylistJournal.read(preferences,"run","changed-list"));String before=preferences.getString("alarmPlaylistPosition","");assertFalse(AlarmPlaylistJournal.save(preferences,"stale","list",1,()->false));assertEquals(before,preferences.getString("alarmPlaylistPosition",""));try(Store store=f.open()){assertFalse(store.backup().toString().contains("alarmPlaylistPosition"));}}finally{f.c.deleteSharedPreferences(name);}}}
}
